import './QrCode.css';

/**
 * STUB: shows a placeholder box. Replace the content with a real QR code of `value`
 * (the invite link) when it is implemented, e.g. with the `qrcode.react` package or an image
 * generated by the backend.
 */
export default function QrCode({ value }) {
  return (
    <div className="qr-code" role="img" aria-label={`QR code for ${value}`}>
      <span className="qr-code__placeholder">QR CODE</span>
    </div>
  );
}
